<div class="page-heading"><div><span class="eyebrow">PEOPLE &amp; BUSINESSES</span><h1>Contacts</h1><p>Your customers and suppliers.</p></div><button class="button primary" data-dialog="contact-dialog"><?= icon('plus') ?>Add contact</button></div><?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Registration number</th><th>Address</th><th></th></tr></thead><tbody><?php foreach($contacts as $c): ?><tr><td><a class="row-title" href="<?= e(url('contacts',['id'=>$c['id']])) ?>"><span class="avatar"><?= e(mb_strtoupper(mb_substr($c['name'],0,1))) ?></span><strong><?= e($c['name']) ?></strong></a></td><td><?= e($c['email']?:'-') ?></td><td><?= e($c['registration_number']?:'-') ?></td><td><?= e($c['address']?:'-') ?></td><td><a class="icon-button" aria-label="Edit <?= e($c['name']) ?>" title="Edit contact" href="<?= e(url('contacts',['id'=>$c['id']])) ?>"><?= icon('settings') ?></a></td></tr><?php endforeach ?><?php if(!$contacts): ?><tr><td colspan="5"><div class="empty-state"><?= icon('users') ?><h3>Keep your contacts together</h3><p>Add a customer or supplier to get started.</p></div></td></tr><?php endif ?></tbody></table></div>
<dialog id="contact-dialog"<?= $contact||$error?' data-open-on-load':'' ?>><div class="dialog-heading"><h2><?= $contact?'Edit':'New' ?> contact</h2><button class="icon-button" data-close-dialog aria-label="Close" title="Close"><?= icon('x') ?></button></div><form method="post" class="stack-form" action="<?= e(url('contacts',$contact?['id'=>$contact['id']]:[])) ?>"><?= csrf_field() ?><label>Name<input name="name" maxlength="190" value="<?= e(is_post()?input('name'):($contact['name']??'')) ?>" required></label><label>Email<input type="email" name="email" maxlength="190" value="<?= e(is_post()?input('email'):($contact['email']??'')) ?>"></label><label>Registration / tax number<input name="registration_number" maxlength="100" value="<?= e(is_post()?input('registration_number'):($contact['registration_number']??'')) ?>"></label><label>Address<textarea name="address" rows="3" maxlength="2000"><?= e(is_post()?input('address'):($contact['address']??'')) ?></textarea></label><button class="button primary"><?= icon('check') ?>Save contact</button></form></dialog>
